parameters.jsCode:
const item = $input.first().json;

// Gemini ka raw text nikalo
let rawText = item.candidates[0].content.parts[0].text;

// agar markdown fences hai (```json ... ```) to hata do
rawText = rawText.replace(/```json|```/g, "").trim();

// JSON array me parse karo
let queries;
try {
  queries = JSON.parse(rawText);
} catch (e) {
  // fallback: agar parse fail ho to line by line split kar do
  queries = rawText.split("\n").filter(q => q.trim().length > 0);
}

return queries.map(q => ({ json: { query: q } }));

const allItems = $input.all();

const combined = allItems.map(item => {
  return {
    query: item.json.query,
    results: (item.json.results || []).map(r => ({
      title: r.title,
      url: r.url,
      content: r.content
    }))
  };
});

const original = $("Code in JavaScript3").first().json;

return [{
  json: {
    pageId: original.pageId,
    title: original.title,
    link: original.link,
    summary: original.summary,
    problem: original.problem,
    claim: original.claim,
    searchRounds: combined
  }
}];

