parameters.jsCode:
const item = $input.first().json;

let rawText = item.candidates[0].content.parts[0].text;
rawText = rawText.replace(/```json|```/g, "").trim();

let verdict;

try {
  verdict = JSON.parse(rawText);
} catch (e) {
  verdict = {
    verified: false,
    explanation: "Could not parse final response.",
    sources: []
  };
}

// Data from Code in JavaScript5 (carries pageId + all searchRounds)
const original = $("Code in JavaScript5").first().json;

const pageId = original.pageId;
const searchRounds = original.searchRounds || [];

// Create readable search log
const queryList = searchRounds
  .map((r, i) => `${i + 1}. ${r.query}`)
  .join("\n");

const searchLogText =
  `Total searches: ${searchRounds.length}\n\n${queryList}`;

// Create final solution text
const solutionText =
  `${verdict.explanation}\n\nSources:\n${(verdict.sources || []).join("\n")}`;

return [{
  json: {
    pageId,
    verified: Boolean(verdict.verified),
    verifiedSolution: solutionText,
    searchLog: searchLogText
  }
}];
